(() => {
  var match = result.match(/params\s*=\s*['"]([^'"]+)['"]/);
  if (!match) return "";
  var params = match[1];

  var allBytes = java.base64DecodeToByteArray(params);
  var ivBytes = allBytes.slice(0, 16);
  var ctBytes = allBytes.slice(16);
  var key = "9S8$vJnU2ANeSRoF";
  key = java.strToBytes(key);
  var cipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, ivBytes);
  var jsonStr = cipher.decryptStr(ctBytes);
  var {images} = JSON.parse(jsonStr);

  var hh = JSON.stringify({"headers": {
    "User-Agent": java.getWebViewUA(),
    "Referer": baseUrl,
    "cookie": cookie.getCookie(baseUrl)
  }});

  return images.map(x=>`<img src="${x+','+hh}">`).join("");
})();

