	| 0;
//是否的切换展示
const selectedStatus = ["⬜","☑️"];
//展开折叠的切换展示
const colspasedStatus = ["📂","📁"];
//连接速度级别标志定义
const speedMark = ["🟩","🟦","🟨","🟧","🟫","🟪","🟥"];
//测速分级标准
const speedGrading = 400;
// [未测试，超级慢，联不通]
const disconnectedMark = ["❓","⬛","⛔"];
/**功能设置初始化*/
//符合条件的网址过滤规则
const checkPairs = {
	"/55/55350/" : "五女神境界（同人续写）"
}
//获取网址的发布页列表
const fetchHostsUrls = ["https://www.wmyqk.com/", "https://diyibanzhu.app/", "http://diyibanzhu.net"];
//域名选择默认值
const defaultHosts = {
	"mumu999999.com" : {
		"url" : "https://www.mumu999999.com/",
		"token" : "",
		"lastTest" : -1,
		"delay" : -1,
		"err" : ""
	}
};
//小说状态
const states = {
	"🎒 全部状态" : 0,
	"✍️ 连载中" : 1,
	"📗 已完结" : 2
};
//小说排序
const orders = {
	"📬️ 最后更新" : "lastupdate",
	"💥 总人气" : "allvisit",
	"🈷️ 月人气"  : "monthvisit",
	"🔢 总字数" : "size",
	"🆕 最新上架" : "postdate"
};
//小说分类
const categories = {
	"📚️全部分类📚️" : 0,
	"🏰玄幻奇幻🔮" : 1,
	"🐉仙侠武侠🐦‍🔥" : 2,
	"🏙️都市言情👩‍❤‍👨" : 3,
	"🌠穿越历史⏳" : 4,
	"🤖科幻灵异👻" : 5,
	"🏫 藏 经 阁 🧙‍♂️" : 6,
	"🍀其他类别❇️" : 7
};
//按作者查询默认值
const defaultAuthors = ["俗人", "棺材里的笑声"];
/**登录及发现界面相关方法*/
//界面内容
var UI = [];
//内容展示模块（disc=发现界面；其他=登录界面）
var MD = "login";
//初始化发现界面参数
const optionsJson = {
	state : [],
	cate : [],
	order : [],
	author : defaultAuthors,
	hosts : [],
	mode : []
};
//初始化小说状态
for (let key in states) {
	optionsJson.state.push(key);
}
//小说排序数组
for (let key in orders) {
	optionsJson.order.push(key);
}
//初始化小说分类
for (let key in categories) {
	optionsJson.cate.push(key);
}
//初始化域名列表
for (let key in defaultHosts) {
	optionsJson.hosts.push(key + " " + disconnectedMark[0]);
	optionsJson.hosts.sort();
}
//生成发现界面链接
const initDiscoverUrl = (java,source,cate,offset) => {
	let args = getArgs(java,source);
	return `{{getHostUrl(java,source)}}shuku/${categories[cate]}-${orders[args.order]}-${states[args.state]}-{{page+${offset>0?offset-1:0}}}.html`;
}
//生成发现界面链接(自定义)
const initDiscoverUrlUD = (status,order,cate,offset) => {
	return `{{getHostUrl(java,source)}}shuku/${categories[cate]}-${orders[order]}-${states[status]}-{{page+${offset>0?offset-1:0}}}.html`;
}
//生成发现界面作者链接
const initDiscoverUrl_A = (author) => {
	return `{{getHostUrl(java,source)}}author.php?author=${author}`;
}
//生成发现界面搜索链接
const initDiscoverUrl_S = (keyWord) => {
	return `{{getHostUrl(java,source)}}s.php,{\\"charset\\":\\"GBK\\",\\"method\\":\\"POST\\",\\"body\\":\\"s=${keyWord}&page={{page }}\\"}`;
}
//切换发现模式
const changeDiscoverMode = (java,source,mode) => {
	let args = getArgs(java,source);
	args.discoverMode = mode;
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
}
//切换工作模式mode:[discover,setting,hosts]
const changeWorkMode = (java, source, mode) => {
	let args = getArgs(java, source);
	args.viewMode = mode;
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
}
//确认参数配置
const conmmitSetting = (java, source, infoMap) => {
	let args = getArgs(java, source);
	//传统发现
	if(args.discoverMode == "discover"){
		args.state = infoMap["state"];
		args.order = infoMap["order"];
		args.keyWord = infoMap["keyWord"].trim();
		args.offset= /[1-9]\d*/.test(infoMap["offset"]) ? infoMap["offset"] : 1;
	}
	args.viewMode = "discover";
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
}
//切换域名
const switchHost = (java, source, infoMap) => {
	let args = getArgs(java, source);
	args.domain = infoMap["domain"];
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
