//基础替换方法
const X = (str, regPair, isLoop) => {
	if (!isLoop) {
		str = String(str).replace(regPair[0], regPair[1]);
		return str;
	}
	while (regPair[0].exec(str)) {
		str = String(str).replace(regPair[0], regPair[1]);
	}
