}
//超时处理
else if(result.code() == 504 || result.code() == 500){
	L(java,64,`${result.url()} 在登录检测时出现超时，重新获取！！\ncode：${result.code()}\ncallTime：${result.callTime()}`);
	L(java,1,"登录检测时出现超时的页面内容\n" + result.body());
	result = java.getStrResponse();
}
//Bad Gateway
else if(result.code() == 502){
	L(java,64,`${result.url()} 在登录检测时出现Bad Gateway，重新获取！！\ncode：${result.code()}\ncallTime：${result.callTime()}`);
	L(java,1,"登录检测时出现Bad Gateway的页面内容\n" + result.body());
	result = java.getStrResponse();
}
else if(result.code() != 200){
	L(java,256,baseUrl + "调用登录检测有问题！返回状态码：" + result.code());
	L(java,1,baseUrl + "返回结果：" + result.body());
}
